#include <iostream>
#include <memory>
#include <string>
using namespace std;

struct Fish {
    string name;
    Fish(string n) : name(n) { cout << "领到 " << name << endl; }
    ~Fish() { cout << "还回 " << name << endl; }
};

void work(bool early) {
    unique_ptr<Fish> p = make_unique<Fish>("{name}");
    if (early) {
        return;
    }
    cout << "用完 " << p->name << endl;
}

int main() {
    work(false);
    cout << "---" << endl;
    work(true);
    cout << "收工" << endl;
    return 0;
}
